contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // We check that calling c.transfer either reverts or returns true, and regardless it does not change
    // the balance of this test contract; if it returns true then the call completed (no revert).
    function run(address from, address caddress, address[] calldata _tos, uint v) public payable {
        require(_tos.length > 0);
        // record our balance before calling
        uint before = address(this).balance;
        bool reverted;
        bool ret;
        // call and capture revert status
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false;
        }
        // After the call: either it reverted, or it returned true. Also the call must not change this contract's balance.
        assert((reverted || ret == true) && address(this).balance == before);
    }
    receive() external payable { }
}

